export function audit(action) {
  return async (req, res, next) => {
    res.on('finish', async () => {
      if (res.statusCode >= 400) return;
      await db('{{table}}').insert({
        user_id: req.user?.id, action,
        route: req.originalUrl, method: req.method,
        ip: req.ip, body: JSON.stringify(req.body),
        ts: new Date(),
      });
    });
    next();
  };
}
